package org.example.items;

public class TaxCalculator {
    private static TaxStrategy getStrategy(String type) {
        return switch (type.toLowerCase()) {
            case "raw" -> new RawTax();
            case "manufactured" -> new ManufacturedTax();
            case "imported" -> new ImportedTax();
            default -> throw new IllegalArgumentException("Invalid item type: " + type);
        };
    }

    public static double calculateSalesTaxPerItem(Item item) {
        TaxStrategy strategy = getStrategy(item.getType());
        return strategy.calculateTax(item.getPrice());
    }

    public static double calculateFinalPricePerItem(Item item) {
        TaxStrategy strategy = getStrategy(item.getType());
        return strategy.calculateFinalPrice(item.getPrice());
    }
}

package org.example.items;

public class TaxCalculator {
    private static TaxStrategy getStrategy(ItemType type) {
        return TaxStrategy.createStrategy(type);
    }

    public static double calculateSalesTaxPerItem(Item item) {
        TaxStrategy strategy = getStrategy(item.getType());
        return strategy.calculateTax(item.getPrice());
    }

    public static double calculateFinalPricePerItem(Item item) {
        TaxStrategy strategy = getStrategy(item.getType());
        return strategy.calculateFinalPrice(item.getPrice());
    }

    public static double calculateTotalPrice(Item item) {
        TaxStrategy strategy = getStrategy(item.getType());
        return strategy.calculateTotalPrice(item);
    }
}

package org.example.items;

public interface TaxStrategy {
    double calculateTax(double price);

    default double calculateFinalPrice(double price) {
        return price + calculateTax(price);
    }
}

package org.example.items;

public interface TaxStrategy {
    double calculateTax(double price);

    default double calculateFinalPrice(double price) {
        return price + calculateTax(price);
    }

    default double roundTax(double amount) {
        return Math.ceil(amount * 20) / 20;
    }

    default double calculateTotalPrice(Item item) {
        double basePrice = item.getPrice() * item.getQuantity();
        return calculateFinalPrice(basePrice);
    }

    static TaxStrategy createStrategy(ItemType type) {
        return switch (type) {
            case RAW -> new RawTax();
            case MANUFACTURED -> new ManufacturedTax();
            case IMPORTED -> new ImportedTax();
        };
    }
}

package org.example.items;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ImportedTaxStrategyTest {
    private final ImportedTax strategy = new ImportedTax();

    @Test
    void calculateTax_PriceBelow100_NoSurcharge() {
        // Given
        double price = 90.0;
        double expectedTax = 9.0; // 10% import duty, no surcharge

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Tax should be 10% with no surcharge");
    }

    @Test
    void calculateTax_PriceBetween100And200_5Surcharge() {
        // Given
        double price = 150.0;
        double importDuty = price * 0.10; // 15.0
        double expectedTax = importDuty + 5; // 20.0

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Tax should include 10% duty and 5 surcharge");
    }

    @Test
    void calculateTax_PriceAbove200_10Surcharge() {
        // Given
        double price = 250.0;
        double importDuty = price * 0.10; // 25.0
        double expectedTax = importDuty + 10; // 35.0

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Tax should include 10% duty and 10 surcharge");
    }

    @Test
    void calculateTotalPrice_ShouldConsiderQuantity() {
        // Given
        Item item = new Item("Imported Item", 150.0, 2, ItemType.IMPORTED);
        double importDuty = 150.0 * 0.10 * 2; // 30.0
        double surcharge = 5.0 * 2; // surcharge applies per item
        double expectedTotal = (150.0 * 2) + importDuty + surcharge; // 340.0

        // When
        double actualTotal = strategy.calculateTotalPrice(item);

        // Then
        assertEquals(expectedTotal, actualTotal, 0.001, "Total price should consider quantity and all taxes");
    }

    @Test
    void roundTax_ShouldRoundUpToNearest5Paise() {
        // Given
        double price = 99.99;
        double importDuty = Math.ceil((price * 0.10) * 20) / 20; // 10.0
        double expectedRoundedTax = importDuty; // No surcharge as price < 100

        // When
        double actualRoundedTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedRoundedTax, actualRoundedTax, 0.001, "Tax should be rounded up to nearest 5 paise");
    }
}

package org.example.items;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class ManufacturedTaxStrategyTest {
    private final ManufacturedTax strategy = new ManufacturedTax();

    @Test
    void calculateTax_ShouldIncludeBaseTaxAndAdditionalTax() {
        // Given
        double price = 100.0;
        // Base tax (12.5%) = 12.5
        // Additional tax (2% of 112.5) = 2.25
        double expectedTax = 14.75;

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Tax should include 12.5% base tax and 2% additional tax");
    }

    @Test
    void calculateFinalPrice_ShouldIncludeAllTaxes() {
        // Given
        double price = 100.0;
        double expectedPrice = 114.75; // price + 12.5 + 2.25

        // When
        double actualPrice = strategy.calculateFinalPrice(price);

        // Then
        assertEquals(expectedPrice, actualPrice, 0.001, "Final price should include all taxes");
    }

    @Test
    void calculateTotalPrice_ShouldConsiderQuantity() {
        // Given
        Item item = new Item("Manufactured Item", 100.0, 2, ItemType.MANUFACTURED);
        double expectedTotal = 229.50; // (100 * 2) + (14.75 * 2)

        // When
        double actualTotal = strategy.calculateTotalPrice(item);

        // Then
        assertEquals(expectedTotal, actualTotal, 0.001, "Total price should consider quantity and all taxes");
    }

    @Test
    void roundTax_ShouldRoundUpToNearest5Paise() {
        // Given
        double price = 99.99;
        // Base tax (12.5%) = 12.49875
        // Additional tax (2% of 112.48875) = 2.24978
        // Total unrounded tax = 14.74853
        double expectedRoundedTax = 14.75;

        // When
        double actualRoundedTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedRoundedTax, actualRoundedTax, 0.001, "Tax should be rounded up to nearest 5 paise");
    }
}

