        // Given
        double price = 100.0;
        double expectedTax = 12.5; // 12.5% of 100

        // When
        double actualTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Raw item tax should be 12.5% of price");
    }

    @Test
    void calculateFinalPrice_ShouldIncludeTax() {
        // Given
        double price = 100.0;
        double expectedPrice = 112.5; // price + 12.5% tax

        // When
        double actualPrice = strategy.calculateFinalPrice(price);

        // Then
        assertEquals(expectedPrice, actualPrice, 0.001, "Final price should include 12.5% tax");
    }

    @Test
    void calculateTotalPrice_ShouldConsiderQuantity() {
        // Given
        Item item = new Item("Raw Material", 100.0, 2, ItemType.RAW);
        double expectedTotal = 225.0; // (100 * 2) + (12.5% * 200)

        // When
        double actualTotal = strategy.calculateTotalPrice(item);

        // Then
        assertEquals(expectedTotal, actualTotal, 0.001, "Total price should consider quantity and tax");
    }

    @Test
    void roundTax_ShouldRoundUpToNearest5Paise() {
        // Given
        double price = 99.99;
        double rawTax = price * 0.125; // 12.49875
        double expectedRoundedTax = 12.50; // Rounds up to nearest 0.05

        // When
        double actualRoundedTax = strategy.calculateTax(price);

        // Then
        assertEquals(expectedRoundedTax, actualRoundedTax, 0.001, "Tax should be rounded up to nearest 5 paise");
    }
}

package org.example.items;

import org.example.items.Item;
import org.example.items.TaxCalculator;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class TaxCalculatorTest {

    @org.junit.Test
    public void calculateSalesTaxPerItem_ForRawItem() {
        // Given
        Item item = new Item("Raw Material", 100.0, 1, "raw");
        double expectedTax = 12.5; // 12.5% of 100

        // When
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Raw item tax calculation failed");
    }

    @Test
    void calculateSalesTaxPerItem_ForManufacturedItem() {
        // Given
        Item item = new Item("Manufactured Item", 100.0, 1, "manufactured");
        double expectedTax = 14.75; // 12.5 + 2% of 112.5

        // When
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Manufactured item tax calculation failed");
    }

    @Test
    void calculateSalesTaxPerItem_ForImportedItem() {
        // Given
        Item item = new Item("Imported Item", 500.0, 1, "imported");
        double expectedTax = 77.5; // 50 (10%) + 27.5 (5% of 550)

        // When
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);

        // Then
        assertEquals(expectedTax, actualTax, 0.001, "Imported item tax calculation failed");
    }

    @Test
    void calculateFinalPricePerItem_ForAllTypes() {
        // Given
        Item rawItem = new Item("Raw Material", 100.0, 1, "raw");
        Item manufacturedItem = new Item("Manufactured Item", 100.0, 1, "manufactured");
        Item importedItem = new Item("Imported Item", 500.0, 1, "imported");

        // When & Then
        assertEquals(112.5, TaxCalculator.calculateFinalPricePerItem(rawItem), 0.001,
                "Raw item final price calculation failed");
        assertEquals(114.75, TaxCalculator.calculateFinalPricePerItem(manufacturedItem), 0.001,
                "Manufactured item final price calculation failed");
        assertEquals(577.5, TaxCalculator.calculateFinalPricePerItem(importedItem), 0.001,
                "Imported item final price calculation failed");
    }

    @Test
    void calculateSalesTaxPerItem_ShouldThrowException_ForInvalidType() {
        // Given
        Item invalidItem = new Item("Invalid", 100.0, 1, "invalid");

        // When & Then
        assertThrows(IllegalArgumentException.class,
                () -> TaxCalculator.calculateSalesTaxPerItem(invalidItem),
                "Should throw IllegalArgumentException for invalid item type");
    }
}

package org.example.items;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TaxCalculatorTest {
    
    @Test
    void calculateSalesTaxPerItem_Raw() {
        Item item = new Item("Raw Material", 100.0, 1, ItemType.RAW);
        double expectedTax = 12.5; // 12.5% of 100
        
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);
        
        assertEquals(expectedTax, actualTax, 0.001, "Raw item tax calculation failed");
    }
    
    @Test
    void calculateSalesTaxPerItem_Manufactured() {
        Item item = new Item("Manufactured Item", 100.0, 1, ItemType.MANUFACTURED);
        double expectedTax = 14.75; // 12.5% base + 2% additional
        
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);
        
        assertEquals(expectedTax, actualTax, 0.001, "Manufactured item tax calculation failed");
    }
    
    @Test
    void calculateSalesTaxPerItem_Imported() {
        Item item = new Item("Imported Item", 150.0, 1, ItemType.IMPORTED);
        double expectedTax = 20.0; // 10% import duty (15) + 5 surcharge
        
        double actualTax = TaxCalculator.calculateSalesTaxPerItem(item);
        
        assertEquals(expectedTax, actualTax, 0.001, "Imported item tax calculation failed");
    }
    
    @Test
    void calculateFinalPricePerItem_Raw() {
        Item item = new Item("Raw Material", 100.0, 1, ItemType.RAW);
        double expectedPrice = 112.5; // price + 12.5% tax
        
        double actualPrice = TaxCalculator.calculateFinalPricePerItem(item);
        
        assertEquals(expectedPrice, actualPrice, 0.001, "Raw item final price calculation failed");
    }
    
    @Test
    void calculateFinalPricePerItem_Manufactured() {
        Item item = new Item("Manufactured Item", 100.0, 1, ItemType.MANUFACTURED);
        double expectedPrice = 114.75; // price + 12.5% base + 2% additional
        
        double actualPrice = TaxCalculator.calculateFinalPricePerItem(item);
        
        assertEquals(expectedPrice, actualPrice, 0.001, "Manufactured item final price calculation failed");
    }
    
    @Test
    void calculateFinalPricePerItem_Imported() {
        Item item = new Item("Imported Item", 150.0, 1, ItemType.IMPORTED);
        double expectedPrice = 170.0; // price + 10% duty + 5 surcharge
        
        double actualPrice = TaxCalculator.calculateFinalPricePerItem(item);
        
        assertEquals(expectedPrice, actualPrice, 0.001, "Imported item final price calculation failed");
    }

    @Test
    void calculateTotalPrice_ShouldConsiderQuantity() {
        Item item = new Item("Raw Material", 100.0, 2, ItemType.RAW);
        double expectedTotal = 225.0; // (100 * 2) + (12.5 * 2)
        
        double actualTotal = TaxCalculator.calculateTotalPrice(item);
        
        assertEquals(expectedTotal, actualTotal, 0.001, "Total price calculation with quantity failed");
    }
}
